+// Append returns a new list containing the nodes of this list followed by node. Repeatedly appending to the
+// latest list reuses spare capacity and derives widths incrementally, so building a list this way is amortized O(1)
+// per node.
+func (s *STNodeList) Append(node STNode) *STNodeList {
+	children := s.appendChildren(node)
+	if len(s.diagnostics) > 0 || s.widthWithMinutiae == 0 {
+		list := createNodeAndAddChildren(&STNodeList{
+			STNodeBase: STNodeBase{kind: LIST},
+			children:   children,
+		}, children...).(*STNodeList)
+		list.ownsSpareCapacity = true
+		return list
+	}
+	list := &STNodeList{
+		STNodeBase:        s.STNodeBase,
+		children:          children,
+		ownsSpareCapacity: true,
+	}
+	if !IsSTNodePresent(node) {
+		return list
+	}
+	if node.HasDiagnostics() {
+		list.flags = list.flags | hasDiagnosticFlag
+	}
+	if node.WidthWithMinutiae() == 0 {
+		return list
+	}
+	list.width = s.widthWithTrailingMinutiae + node.WidthWithLeadingMinutiae()
+	list.widthWithLeadingMinutiae = s.widthWithMinutiae + node.WidthWithLeadingMinutiae()
+	list.widthWithTrailingMinutiae = s.widthWithTrailingMinutiae + node.WidthWithMinutiae()
+	list.widthWithMinutiae = s.widthWithMinutiae + node.WidthWithMinutiae()
+	return list
+}
+
+func (s *STNodeList) appendChildren(node STNode) []STNode {
+	if s.ownsSpareCapacity && len(s.children) < cap(s.children) {
+		s.ownsSpareCapacity = false
+		return append(s.children, node)
+	}
+	children := make([]STNode, len(s.children), 2*len(s.children)+1)
+	copy(children, s.children)
+	return append(children, node)
+}
